// 英文法テストの答え合わせで、4つの選択肢を1つずつ説明する文（問題 id → 選択肢 → 説明）。
// 正解には「なぜその形になるか」、誤答には「なぜこの文に入らないか」を、その問題の文に当てはめて書く。
// 自動生成の問題は grammar-generated.js の各問題が choiceNotes として同じ説明を持つ。
const freezeNotes = (notes) => Object.freeze(Object.fromEntries(
  Object.entries(notes).map(([id, byChoice]) => [id, Object.freeze(byChoice)]),
))

